insert into public.exercises
  (id, name, description, category, stroke, fftt_stage, stage_label, level, difficulty, lieu, duration_min, video_id, video_url, video_source, pro_id, tags, sort)
values
  ('drill_jonglage_base', 'Jonglage de base', 'Faire des rebonds sur la raquette sans faire tomber la balle. Maitriser la trajectoire verticale. Ameliorer son score a chaque passage.', 'juggling', 'Toucher de balle', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 4, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"jonglage","controle","debutant","solo"}', 0),
  ('drill_jonglage_cd', 'Jonglage coup droit', 'Rebonds uniquement cote coup droit, raquette horizontale. Stabiliser le contact balle-raquette du cote coup droit.', 'juggling', 'Coup droit', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 4, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"jonglage","coup_droit","debutant","solo"}', 1),
  ('drill_jonglage_revers', 'Jonglage revers', 'Rebonds uniquement cote revers. Travaille le toucher de balle du cote faible chez la majorite des debutants.', 'juggling', 'Revers', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 4, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"jonglage","revers","debutant","solo"}', 2),
  ('drill_jonglage_alterne', 'Jonglage alterne CD/revers', 'Alterner un rebond coup droit puis un rebond revers (rotation du poignet). Prepare la differenciation coup droit / revers.', 'juggling', 'Toucher de balle', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 4, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"jonglage","liaison","poignet","solo"}', 3),
  ('drill_jonglage_hauteurs', 'Jonglage hauteurs variees', 'Faire varier la hauteur des rebonds (bas/haut) sans perdre le controle. Dosage de l''energie du geste.', 'juggling', 'Toucher de balle', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 5, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"jonglage","dosage","controle","solo"}', 4),
  ('drill_parcours_balle', 'Parcours balle sur raquette', 'Se deplacer sur un slalom (plots/cerceaux) en gardant la balle posee sur la raquette sans la faire tomber. Concentration, tonicite, mobilite du poignet.', 'skill', 'Toucher de balle', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 5, NULL, 'https://www.pingskills.com/tutorials/table-tennis-strokes/most-important-skill', 'PingSkills', NULL, '{"coordination","equilibre","mobilite","solo"}', 5),
  ('drill_mur_cd', 'Jeu contre le mur — coup droit', 'Renvoyer la balle cote coup droit contre un mur, 3 fois de suite minimum. Position du corps et de la raquette, concentration. Varier les vitesses.', 'drive', 'Coup droit', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'mur', 6, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"coup_droit","regularite","mur","solo"}', 6),
  ('drill_mur_revers', 'Jeu contre le mur — revers', 'Renvoyer la balle cote revers contre un mur, 3 fois de suite minimum. Stabiliser le geste revers en autonomie.', 'drive', 'Revers', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'mur', 6, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"revers","regularite","mur","solo"}', 7),
  ('drill_mur_alterne', 'Jeu contre le mur — alterne CD/revers', 'Renvoyer alternativement coup droit puis revers contre le mur, 2 fois de suite minimum. Premiere liaison des deux coups.', 'drive', 'Technique de déplacement', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'mur', 6, 'aG40Jnpi0EU', 'https://www.youtube.com/watch?v=aG40Jnpi0EU', 'PingSkills', NULL, '{"liaison","mur","solo"}', 8),
  ('drill_service_regl_cd', 'Service reglementaire place — coup droit', 'Lancer la balle, la frapper dans la descente, un rebond de chaque cote. Reussir 7 a 10 services sur 10. Sans effet, place.', 'service', 'Service', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'table_solo', 6, NULL, 'https://www.tabletenniscoach.me.uk/improve-serves-solo-service-practice/', 'PingSkills', NULL, '{"service","reglementaire","coup_droit","solo"}', 9),
  ('drill_service_regl_revers', 'Service reglementaire place — revers', 'Service revers sans effet, place et reglementaire. Reussir 7 a 10 sur 10. Base du service avant maquillage des effets.', 'service', 'Service', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'table_solo', 6, '_LhmBGTRlCE', 'https://www.youtube.com/watch?v=_LhmBGTRlCE', 'PingSkills', NULL, '{"service","reglementaire","revers","solo"}', 10),
  ('drill_renvoi_cd_demi', 'Renvoi regulier — coup droit demi-table', 'Maintenir un echange regulier en coup droit sur la demi-table adverse. Geste simple oriente vers l''avant et le haut.', 'drive', 'Coup droit', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'table_duo', 8, 'GxAqmTLZLh0', 'https://www.youtube.com/watch?v=GxAqmTLZLh0', 'PingSkills', NULL, '{"coup_droit","regularite","echange"}', 11),
  ('drill_renvoi_revers_demi', 'Renvoi regulier — revers demi-table', 'Maintenir un echange regulier en revers sur la demi-table adverse. Stabiliser le geste de renvoi revers.', 'drive', 'Revers', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'table_duo', 8, 'W_ZfwwhGsl8', 'https://www.youtube.com/watch?v=W_ZfwwhGsl8', 'PingSkills', NULL, '{"revers","regularite","echange"}', 12),
  ('drill_deplacement_lateral', 'Deplacements lateraux simples', 'Pas chasses lateraux courts a vide ou sur balle facile, jambes flechies, allegement des appuis. Apprendre a bouger juste.', 'footwork', 'Technique de déplacement', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 5, 'f3QwxKWHKbU', 'https://www.youtube.com/watch?v=f3QwxKWHKbU', 'Tom Lodziak', NULL, '{"deplacement","appuis","mobilite","solo"}', 13),
  ('drill_echauffement_hors_table', 'Echauffement hors table — jeux d''opposition', 'Jeux de poursuite et d''opposition hors table : developpe la mobilite, le cote malin et l''attitude dynamique.', 'fitness', 'Vitesse de déplacement', 'prepaping', 'Balle Blanche', 'Débutant', NULL, 'maison', 8, '3GJyHzf15N8', 'https://www.youtube.com/watch?v=3GJyHzf15N8', 'PingSkills', NULL, '{"echauffement","mobilite","ludique"}', 14),
  ('drill_cd_50_echanges', 'Coup droit moitie de table — 50 echanges', 'Le partenaire (ou robot) joue uniquement dans le coup droit. Objectif : 50 echanges consecutifs sans faute. Monter l''intensite progressivement.', 'drive', 'Coup droit', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 10, 'GxAqmTLZLh0', 'https://www.youtube.com/watch?v=GxAqmTLZLh0', 'PingSkills', NULL, '{"coup_droit","regularite","placement"}', 15),
  ('drill_revers_regularite', 'Revers moitie de table — regularite', 'Echange regulier en revers, 50 balles cibles. Stabiliser la frappe revers avant d''accelerer.', 'drive', 'Revers', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 10, 'GI7rX5-90DQ', 'https://www.youtube.com/watch?v=GI7rX5-90DQ', 'PingSkills', NULL, '{"revers","regularite"}', 16),
  ('drill_placement_lateral_cd', 'Placement lateral — croiser/decroiser coup droit', 'Jouer le coup droit alternativement en diagonale puis en ligne (decroiser). Maitriser l''orientation du geste et de la raquette.', 'drive', 'Coup droit', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 10, 'QjB6P3Ht1jc', 'https://www.youtube.com/watch?v=QjB6P3Ht1jc', 'Ping To Pong', NULL, '{"placement","diagonale","ligne","coup_droit"}', 17),
  ('drill_liaison_cd_revers_1_1', 'Liaison coup droit / revers (1-1)', 'Un coup droit, un revers en alternance regulier. Equilibrage CD/revers, replacement entre les deux coups.', 'footwork', 'Technique de déplacement', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 10, 'phM_uZ1IDDU', 'https://www.youtube.com/watch?v=phM_uZ1IDDU', 'PingSkills', NULL, '{"liaison","replacement","coup_droit","revers"}', 18),
  ('drill_service_court_sans_effet', 'Service court place sans effet', 'Service court (deux rebonds cote adverse) place, sans effet. Base avant le travail des effets et du maquillage.', 'service', 'Service', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_solo', 8, 'h2YDRVhz08I', 'https://www.youtube.com/watch?v=h2YDRVhz08I', 'PingSkills', NULL, '{"service","court","placement","solo"}', 19),
  ('drill_service_long_rapide', 'Service long rapide', 'Service long et rapide qui rebondit pres de la ligne de fond adverse. Vitesse + placement, sans le rendre lisible.', 'service', 'Service', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_solo', 8, '4lQP33tJJfg', 'https://www.youtube.com/watch?v=4lQP33tJJfg', 'PingSkills', NULL, '{"service","long","vitesse","solo"}', 20),
  ('drill_retour_service_place', 'Retour de service place', 'Remettre le service de maniere placee (pas seulement remettre : choisir une zone). Lecture trajectoire + decision.', 'return', 'Remise de service', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 8, '-03N_1zOM4E', 'https://www.youtube.com/watch?v=-03N_1zOM4E', 'PingSkills', NULL, '{"retour","remise","placement"}', 21),
  ('drill_deplacement_pivot', 'Deplacement lateral + pivot', 'Travailler le deplacement lateral puis le pivot (se decaler pour jouer coup droit cote revers). Coordination jambes.', 'footwork', 'Technique de déplacement', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 8, '6_kTGwxqeMM', 'https://www.youtube.com/watch?v=6_kTGwxqeMM', 'Tom Lodziak', NULL, '{"deplacement","pivot","footwork"}', 22),
  ('drill_cd_croise_ligne', 'Coup droit croise et ligne droite', 'Alterner un coup droit croise (diagonale) avec un coup droit en ligne droite. Varier puissance et rotation (top-spin, frappe seche, balle lente).', 'drive', 'Coup droit', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 10, 'sMsSiRbMrUs', 'https://www.youtube.com/watch?v=sMsSiRbMrUs', 'Tom Lodziak', NULL, '{"coup_droit","diagonale","ligne","variation"}', 23),
  ('drill_cd_deplacement_aleatoire', 'Coup droit avec deplacement (balle aleatoire)', 'Le partenaire envoie la balle aleatoirement dans la demi-table : se deplacer pour tout jouer en coup droit, retour en position neutre apres chaque coup.', 'footwork', 'Technique de déplacement', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_robot', 10, 'RUQcMuzgVBI', 'https://www.youtube.com/watch?v=RUQcMuzgVBI', 'Table Tennis University', NULL, '{"coup_droit","deplacement","appuis","replacement"}', 24),
  ('drill_panier_contre_attaque_cd', 'Panier de balles — contre-attaque coup droit', 'Le distributeur envoie des balles au panier, le joueur enchaine des contre-attaques coup droit. Accelere l''apprentissage du coup.', 'drive', 'Coup droit', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_robot', 8, NULL, NULL, 'FFTT (a filmer)', NULL, '{"panier","contre_attaque","coup_droit"}', 25),
  ('drill_jeux_comptes', 'Jeux comptes / formes competitives', 'Mini-matchs avec contrainte (zones imposees, sets courts). Developpe le gain du point et le cote malin/combatif.', 'match', 'Lecture de jeu', 'baseping', 'Balle Orange', 'Débutant', NULL, 'table_duo', 12, 'XsZp8nTjZ2c', 'https://www.youtube.com/watch?v=XsZp8nTjZ2c', 'TableTennisDaily', NULL, '{"match","competition","tactique"}', 26),
  ('drill_educatifs_pied', 'Educatifs du pied / coordination', 'Echelle de rythme, pas chasses, sauts : coordination et legerete des appuis specifique tennis de table.', 'fitness', 'Vitesse de déplacement', 'baseping', 'Balle Orange', 'Débutant', NULL, 'maison', 8, 'f3QwxKWHKbU', 'https://www.youtube.com/watch?v=f3QwxKWHKbU', 'Tom Lodziak', NULL, '{"coordination","appuis","fitness","solo"}', 27),
  ('drill_topspin_cd_coupe', 'Top-spin coup droit sur balle coupee', 'Le partenaire pousse des balles coupees dans le coup droit : demarrer en top-spin en relevant la balle (angle de raquette + rotation), avec controle.', 'topspin', 'Coup droit', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_robot', 10, 'NWw_1SO3TV0', 'https://www.youtube.com/watch?v=NWw_1SO3TV0', 'PingSkills', NULL, '{"topspin","coup_droit","demarrage","balle_coupee"}', 28),
  ('drill_topspin_revers_coupe', 'Top-spin revers sur balle coupee', 'Demarrer en top-spin revers sur poussette coupee. Frotter la balle par-dessous puis par-dessus, qualite du contact.', 'topspin', 'Revers', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_robot', 10, 'NWw_1SO3TV0', 'https://www.youtube.com/watch?v=NWw_1SO3TV0', 'PingSkills', NULL, '{"topspin","revers","demarrage","balle_coupee"}', 29),
  ('drill_poussette_cd', 'Poussette coup droit — regularite', 'Echange de poussettes coupees en coup droit. Frotter par-dessous, garder court et bas. Base du petit jeu.', 'push', 'Poussette', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 8, 'Hx5ZQSsmFjo', 'https://www.youtube.com/watch?v=Hx5ZQSsmFjo', 'PingSkills', NULL, '{"poussette","coup_droit","coupe","petit_jeu"}', 30),
  ('drill_poussette_revers', 'Poussette revers — regularite', 'Echange de poussettes revers, balle coupee et basse. Le coup le plus utilise dans le petit jeu.', 'push', 'Poussette', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 8, 'Hx5ZQSsmFjo', 'https://www.youtube.com/watch?v=Hx5ZQSsmFjo', 'PingSkills', NULL, '{"poussette","revers","coupe","petit_jeu"}', 31),
  ('drill_bloc_revers', 'Bloc revers contre top-spin', 'Bloquer le top-spin adverse en revers : angle de raquette ferme, absorption. Controle de la rotation avant adverse.', 'block', 'Bloc revers', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 8, 'q-gQutk9tgo', 'https://www.youtube.com/watch?v=q-gQutk9tgo', 'PingSkills', NULL, '{"bloc","revers","defense","topspin_adverse"}', 32),
  ('drill_bloc_cd', 'Bloc coup droit contre top-spin', 'Bloc coup droit actif/passif contre top-spin. Tenir la table, controler la balle a mi-distance.', 'block', 'Bloc coup droit', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 8, 'V021kGUUTsU', 'https://www.youtube.com/watch?v=V021kGUUTsU', 'PingSkills', NULL, '{"bloc","coup_droit","defense"}', 33),
  ('drill_service_attaque_3e_balle', 'Enchainement service + attaque 3e balle', 'Servir (court coupe ou lateral) puis attaquer en coup droit sur la remise. Alterner attaque diagonale et ligne. Schema tactique de base.', 'tactic', 'Service', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 12, 'zYOwkAb302k', 'https://www.youtube.com/watch?v=zYOwkAb302k', 'Spin Your Enemy', NULL, '{"service","3e_balle","attaque","schema"}', 34),
  ('drill_play_opening_up', 'Schema "Opening up" (Larcombe)', '1) Service court coupe au milieu. 2) Adversaire pousse long (dig) coup droit. 3) Top-spin coup droit ligne sur revers. 4) Bloc revers adverse. 5) Top-spin revers ligne. 6) Jeu libre. Travaille l''attaque 3e balle sur balle coupee.', 'tactic', 'Lecture de jeu', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 12, 'NWw_1SO3TV0', 'https://www.youtube.com/watch?v=NWw_1SO3TV0', 'PingSkills', NULL, '{"schema","service_court","topspin","3e_balle"}', 35),
  ('drill_topspin_sur_bloc', 'Top-spin sur bloc — regularite', 'Le partenaire bloque, le joueur enchaine des top-spins coup droit reguliers. Continuite + qualite de contact.', 'topspin', 'Coup droit', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 10, 'BpVAPPzj3ZI', 'https://www.youtube.com/watch?v=BpVAPPzj3ZI', 'PingSkills', NULL, '{"topspin","bloc","regularite","enchainement"}', 36),
  ('drill_falkenberg', 'Falkenberg drill (revers — pivot CD — CD)', 'Sequence : revers coin revers, puis pivot coup droit depuis le coin revers, puis coup droit grand cote. Footwork lateral + step-around. Rester equilibre, revenir vite en position.', 'footwork', 'Technique de déplacement', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 10, '4D4Tvm9r_ug', 'https://www.youtube.com/watch?v=4D4Tvm9r_ug', 'Dublin Table Tennis Club', NULL, '{"falkenberg","footwork","pivot","deplacement"}', 37),
  ('drill_match_theme_cd', 'Match a theme — jouer uniquement coup droit', 'Match en forcant l''utilisation du coup droit (si possible). Renforce les automatismes et le positionnement en situation.', 'match', 'Coup droit', 'jeuping', 'Bronze', 'Intermédiaire', NULL, 'table_duo', 10, NULL, 'https://www.pingskills.com/tutorials/table-tennis-training-further-learning/the-practice-routine-that-will-transform-your-table-tennis-game', 'PingSkills', NULL, '{"match","theme","coup_droit","tactique"}', 38),
  ('drill_play_flicking_out', 'Schema "Flicking out" (Larcombe)', '1) Service court coupe ligne. 2) Touch coup droit adverse sur revers. 3) Flip revers diagonale. 4) Bloc adverse ligne. 5) Top-spin coup droit diagonale. 6) Libre. Travaille l''attaque 3e balle au flip.', 'tactic', 'Lecture de jeu', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 12, 'ytqn4FQASNI', 'https://www.youtube.com/watch?v=ytqn4FQASNI', 'Tom Lodziak', NULL, '{"schema","flip","3e_balle","service_court"}', 39),
  ('drill_play_short_topspin', 'Schema "Short topspin serve" (Larcombe)', '1) Service court lifte ligne. 2) Flip coup droit adverse large CD. 3) Top-spin coup droit milieu. 4) Bloc coup droit adverse milieu. 5) Top-spin coup droit revers. 6) Libre. Etre pret a topspiner derriere un flip adverse.', 'tactic', 'Lecture de jeu', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 12, 'sEdPqz4UfdM', 'https://www.youtube.com/watch?v=sEdPqz4UfdM', 'Acceleraq', NULL, '{"schema","service_lifte","topspin"}', 40),
  ('drill_play_touch_open_up', 'Schema "Touch & open up" (retour, Larcombe)', '1) Adversaire sert court coupe milieu. 2) Touch coup droit sur son coup droit. 3) Dig coup droit adverse milieu. 4) Open-up coup droit sur son revers. 5) Libre. Travaille la remise courte + ouverture 4e balle.', 'tactic', 'Lecture de jeu', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 12, 'CvevK1yKl8s', 'https://www.youtube.com/watch?v=CvevK1yKl8s', 'PingSkills', NULL, '{"schema","retour","touch","open_up","4e_balle"}', 41),
  ('drill_play_dig_counter', 'Schema "Dig & counter" (retour, Larcombe)', '1) Adversaire sert court coupe revers. 2) Dig revers profond sur son coup droit. 3) Top-spin coup droit adverse (open up). 4) Contre top-spin coup droit dans son crossover. 5) Libre. Anticiper l''attaque sur la poussette longue.', 'tactic', 'Lecture de jeu', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 12, 'J_8yZa3b7P4', 'https://www.youtube.com/watch?v=J_8yZa3b7P4', 'Ti Long', NULL, '{"schema","retour","dig","contre","anticipation"}', 42),
  ('drill_defense_coupee', 'Defense coupee (loin de la table)', 'Defendre en coupant loin de la table pour ramener la balle longue avec rotation arriere. Affiner les sensations balle-raquette.', 'defense', 'Défense coup droit', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 10, 'gSSlb_5aEvk', 'https://www.youtube.com/watch?v=gSSlb_5aEvk', 'Tom Lodziak', NULL, '{"defense","coupee","rotation","loin_table"}', 43),
  ('drill_defense_haute_liftee', 'Defense haute liftee', 'Defendre en liftant haut pour repousser l''attaque adverse loin. Variante de defense a maitriser cote techniping.', 'defense', 'Défense revers', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 10, 'Hnpw8WfdLWg', 'https://www.youtube.com/watch?v=Hnpw8WfdLWg', 'PingSkills', NULL, '{"defense","liftee","haute"}', 44),
  ('drill_poussette_courte_longue', 'Poussette courte vs longue tendue', 'Varier poussette courte (deux rebonds) et poussette longue tendue (rapide, profonde) pour gener le demarrage adverse.', 'push', 'Poussette', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 10, 'Hx5ZQSsmFjo', 'https://www.youtube.com/watch?v=Hx5ZQSsmFjo', 'PingSkills', NULL, '{"poussette","variation","court","long","petit_jeu"}', 45),
  ('drill_flip_balle_courte', 'Flip sur balle courte', 'Attaquer une balle courte au flip (coup droit ou revers). Solution offensive sur le jeu court, peu utilisee a ce niveau.', 'topspin', 'Flip coup droit', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 8, 'mC0H6OLL_4M', 'https://www.youtube.com/watch?v=mC0H6OLL_4M', 'PingSkills', NULL, '{"flip","balle_courte","attaque"}', 46),
  ('drill_jeu_de_contre', 'Jeu de contre (mi-distance)', 'Echange de contre-attaques top-spin contre top-spin a mi-distance. Resister a la pression, se creer des occasions par vitesse/placement.', 'counter', 'Top sur top', 'techniping', 'Argent', 'Avancé', NULL, 'table_duo', 10, '-3O1JaVzMDw', 'https://www.youtube.com/watch?v=-3O1JaVzMDw', 'PingSkills', NULL, '{"contre","topspin","mi_distance","pression"}', 47),
  ('drill_gainage_posture', 'Gainage + posture pongiste', 'Renforcement gainage et posture specifique : stabilite du tronc pour la chaine cinetique. Maintenir chaque position 20-30s.', 'fitness', 'Vitesse de déplacement', 'techniping', 'Argent', 'Avancé', NULL, 'maison', 10, NULL, NULL, 'FFTT (a filmer)', NULL, '{"gainage","posture","fitness","prepa_physique","solo"}', 48),
  ('drill_gestion_temps_repos', 'Gestion des temps de repos entre les points', 'Routine entre les points : respiration, regard, reset mental. Travaille la presence (axe 3 Josias) et la gestion d''une partie.', 'mental', 'Lecture de jeu', 'techniping', 'Argent', 'Avancé', NULL, 'maison', 5, 'YdhtpH-h3rE', 'https://www.youtube.com/watch?v=YdhtpH-h3rE', 'Tom Lodziak', NULL, '{"mental","presence","routine","reset"}', 49),
  ('drill_play_long_pendulum', 'Schema "Long pendulum" (Larcombe)', '1) Service lateral pendulum long, large revers. 2) Top-spin revers adverse. 3) Contre top-spin revers milieu. 4) Bloc coup droit adverse. 5) Top-spin coup droit diagonale. 6) Libre. Gerer le 3e ballon cote revers apres service lateral long.', 'tactic', 'Lecture de jeu', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 12, 'NFCgf-41SmM', 'https://www.youtube.com/watch?v=NFCgf-41SmM', 'Tom Lodziak', NULL, '{"schema","service_lateral","long","contre"}', 50),
  ('drill_play_down_the_line', 'Schema "Down the line" (Larcombe)', '1) Service rapide lifte ligne sur coup droit. 2) Top-spin coup droit adverse. 3) Contre coup droit milieu. 4) Bloc revers adverse milieu. 5) Top-spin coup droit milieu. 6) Libre. Pince l''adversaire sur son crossover.', 'tactic', 'Lecture de jeu', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 12, 'Q5x4kraM2ZI', 'https://www.youtube.com/watch?v=Q5x4kraM2ZI', 'PingSkills', NULL, '{"schema","service_ligne","rapide","crossover"}', 51),
  ('drill_play_topspin_counter', 'Schema "Topspin & counter" (retour, Larcombe)', '1) Adversaire sert lateral long large revers. 2) Top-spin revers sur son milieu. 3) Contre top-spin coup droit adverse. 4) Contre coup droit en diagonale. 5) Libre. Rester a la table en topspin-topspin.', 'tactic', 'Lecture de jeu', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 12, 'aOEJAKVZqVg', 'https://www.youtube.com/watch?v=aOEJAKVZqVg', 'Ti Long', NULL, '{"schema","retour","contre","agressif"}', 52),
  ('drill_play_topspin_topspin', 'Schema "Topspin & topspin" (retour, Larcombe)', '1) Adversaire sert long lifte milieu. 2) Top-spin coup droit fort large CD. 3) Bloc coup droit adverse. 4) Top-spin coup droit diagonale. 5) Libre. Forcer le bloc puis finir au 4e ballon.', 'tactic', 'Lecture de jeu', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 12, 'ERophnSXQCo', 'https://www.youtube.com/watch?v=ERophnSXQCo', 'PingSkills', NULL, '{"schema","retour","topspin","4e_balle","finition"}', 53),
  ('drill_irregularite_4e_balle', 'Irregularite 4e balle (anticipation)', 'Schema dirige ou le 4e ballon adverse part au choix revers OU coup droit : le joueur doit attendre et anticiper avant de jouer le 5e. Travaille l''axe anticipation (Josias).', 'tactic', 'Réactivité', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 12, 'Wg_GJsHQpTE', 'https://www.youtube.com/watch?v=Wg_GJsHQpTE', 'Acceleraq', NULL, '{"anticipation","irregularite","lecture","demi_libre"}', 54),
  ('drill_variation_rythme_rotation', 'Variation rythme/rotation sur un meme coup', 'Jouer le meme coup en variant rotation, puissance, vitesse, hauteur, trajectoire pour destabiliser l''adversaire. Coeur de l''etape excelping.', 'drive', 'Toucher de balle', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 10, '30zKrRSY0PE', 'https://www.youtube.com/watch?v=30zKrRSY0PE', 'PingSkills', NULL, '{"variation","rotation","rythme","destabiliser"}', 55),
  ('drill_coup_terminal_systeme', 'Coup terminal adapte au systeme de jeu', 'Construire et repeter le coup qui termine le point selon son systeme de jeu (ex : top-spin coup droit diagonale). Rentabiliser son ADN.', 'tactic', 'Coup droit', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 10, 'T8dHrFpZ8LA', 'https://www.youtube.com/watch?v=T8dHrFpZ8LA', 'PingSkills', NULL, '{"coup_terminal","systeme_de_jeu","finition","adn"}', 56),
  ('drill_service_relance_signature', 'Service + relance signature (ADN de jeu)', 'Travailler la combinaison service prefere -> enchainement signature adapte a son systeme de jeu et a l''adversaire. Schema personnel a optimiser.', 'tactic', 'Service', 'excelping', 'Or', 'Expert', NULL, 'table_duo', 12, 'eMUPrs3vvpI', 'https://www.youtube.com/watch?v=eMUPrs3vvpI', 'PingSkills', NULL, '{"service","schema_signature","adversaire","adn"}', 57),
